return {api_version=1,id="CS2_045", rarity = "free",name="Rockbiter Weapon",text="Give a friendly character +3 Attack this turn.",set="LEGACY",type="spell",class="shaman",spell_school="nature",cost=2,target_mode="required",targets=function(ctx,self)local p=ctx:controller(self);local r={ctx:player(p).hero};for _,e in ipairs(ctx:friendly_minions(self))do r[#r+1]=e end;return r end,on_play=function(ctx,self,target)ctx:buff_until_end_of_turn(target,3,0)end}
